#include "stdafx.h"#include "TrendsRsuKernelInfinite.h"#include <time.h>KTrendsRsuKernelInfinite::KTrendsRsuKernelInfinite(): m_nInterval(1), m_nSizeMB(100), m_dCurTime(0.0), m_bInit(false), m_FileDurationS( 60 )//, m_nSizeVar(0)//, m_hMapHead(NULL), m_dwBklTotal(0), m_dwBlkAlloc(maxBlocksOut)//, m_pHeadT(NULL), m_pDataT(NULL), pbBegWnd(NULL)//, m_AllocLeft( 0 ), m_nStep( 0 ){  m_hMapData[0] = m_hMapData[1] = NULL;}KTrendsRsuKernelInfinite::~KTrendsRsuKernelInfinite(){  Close();}void KTrendsRsuKernelInfinite::Close(){  if( pbBegWnd )    ::UnmapViewOfFile( pbBegWnd );  if( m_pHeadT )    ::UnmapViewOfFile( m_pHeadT );  if( m_hMapHead )    ::CloseHandle( m_hMapHead );  if( m_hMapData[0] )    ::CloseHandle( m_hMapData[0] );  if( m_hMapData[1] )    ::CloseHandle( m_hMapData[1] );  pbBegWnd = NULL;  m_pHeadT = NULL;  m_hMapHead = NULL;  m_hMapData[0] = m_hMapData[1] = NULL;}int KTrendsRsuKernelInfinite::StepK0(){  // Чтобы была запись при первом шаге  m_dCurTime = (double)m_nInterval;  return 0;}int KTrendsRsuKernelInfinite::StepKT( double dtH, time_t StartTime ){  if( !m_bInit )  {    FillArray();    {      // Обнуляем содержимое файла трендов      //CSemLock LockIniTrends ( "Trends access", 5000 );      if( !OpenTrendHead() )        return 1;      if( !OpenTrendData(m_pHeadT->dwName) )        return 1;    }    FillHeader();    m_pHeadT->kBlk = m_dwBklTotal;    m_pHeadT->kVar = Count();    m_bInit = true;        //Для отображения в АРМ-ах модельного времени    m_pHeadT->trendsStartTime = m_pHeadT->StartTime = StartTime;    // Количество записей    unsigned __int64 dwCountWrite = 0;    if( m_nSizeVar > 0 )      dwCountWrite = GetTrendSize()/m_nSizeVar;    //  }  //  m_dCurTime += dtH*3600.;  while( m_dCurTime >= m_nInterval )  {    WriteTrends();    m_dCurTime -= m_nInterval;  }  return 0;}